// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    receive() external payable {
        if (c.getBalance(address(this)) == 1 ether) {
            // Only reenter if we are inside withdrawBalance (i.e., balance is non-zero before call)
            // This prevents infinite loop.
            c.addToBalance{value: msg.value}();
        }
    }

    function testRegression_property() public {
        // Fund this contract with 2 ether: 1 for initial deposit, 1 for reentrant.
        vm.deal(address(this), 2 ether);

        // Initial deposit
        c.addToBalance{value: 1 ether}();

        // Now withdrawBalance will trigger receive, which reenters addToBalance
        // In reference: nonReentrant on addToBalance reverts -> send fails -> withdrawBalance reverts
        // In bug: reentrant addToBalance succeeds -> send succeeds -> balance set to 0

        bool withdrawSuccess;
        try c.withdrawBalance() {
            withdrawSuccess = true;
        } catch {
            withdrawSuccess = false;
        }

        // After the call, check userBalance[address(this)]
        // Reference: withdraw reverts, balance remains 1 ether
        // Bug: withdraw succeeds, balance becomes 0
        uint256 balanceAfter = c.getBalance(address(this));
        assertTrue(withdrawSuccess == false); // In reference it reverts, in bug it doesn't
        // Actually to be precise: reference reverts, so withdrawSuccess false; bug does not revert, so true.
        // We can assert that balanceAfter == 1 ether (reference) vs bug 0.
        // But we can only have one assertion. Let's assert the balance.
        // In reference, balance after should be 1 ether; in bug, 0.
        assertTrue(balanceAfter == 1 ether);
    }
}

