pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund caller B (0x02) with 1 ether for gas and 1 wei balance in contract
        address attacker = address(0x02);
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        c.addToBalance{value: 1}();  // B's balance = 1

        // Create a malicious contract that reenters addToBalance on receive
        address reentrant = address(new Reentrant(c));
        vm.deal(reentrant, 1 wei);

        // Fund reentrant's balance in contract (call from reentrant directly)
        vm.prank(reentrant);
        c.addToBalance{value: 1}();  // reentrant's balance = 1

        // Now attacker calls withdrawBalance, which will send ether to reentrant
        // reentrant's fallback calls c.addToBalance{value: 1}() again
        vm.prank(reentrant);
        c.withdrawBalance();

        // Reference: reentrancy blocked, so reentrant's balance becomes 0
        // Buggy: reentrancy succeeds, so reentrant's balance becomes 1
        // Check reentrant's balance in the contract
        uint256 balance = c.getBalance(address(reentrant));
        assertTrue(balance == 0, "Balance should be 0 in correct contract");
    }
}

contract Reentrant {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {
        // Reenter addToBalance with 1 wei
        c.addToBalance{value: 1}();
    }
}

